import{_ as t,o,c as a,a5 as r}from"./chunks/framework.CsGesDJn.js";const f=JSON.parse('{"title":"Sequence Flow — Update Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/profile/3-3-2-update-profile/sequence-flow.md","filePath":"feature/profile/3-3-2-update-profile/sequence-flow.md"}'),d={name:"feature/profile/3-3-2-update-profile/sequence-flow.md"};function i(l,e,s,n,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="sequence-flow-—-update-profile" tabindex="-1">Sequence Flow — Update Profile <a class="header-anchor" href="#sequence-flow-—-update-profile" aria-label="Permalink to &quot;Sequence Flow — Update Profile&quot;">​</a></h1><p>&gt; Supplements <code>spec.md</code> (FR 3.3.2). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly — it does not restate business rules (see spec.md for those). &gt; &gt; Updated: 2026-09-25. Matches the current implementation.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>User</strong> — the signed-in user.</li><li><strong>Client</strong> — the Profile screen at <code>/settings/profile</code> and the avatar upload dialog.</li><li><strong>System</strong> — <code>UserController</code> / <code>UserServiceImpl</code>.</li><li><strong>Database</strong> — PostgreSQL (<code>users</code>).</li><li><strong>File Storage</strong> — object storage holding avatar images.</li></ul><hr><h2 id="flow-a-—-update-the-profile-fields-full-name-phone-professional-title-bio-portfolio-urls-working-language-timezone-notification-preferences" tabindex="-1">Flow A — Update the profile fields (full name, phone, professional title, bio, portfolio URLs, working language, timezone, notification preferences) <a class="header-anchor" href="#flow-a-—-update-the-profile-fields-full-name-phone-professional-title-bio-portfolio-urls-working-language-timezone-notification-preferences" aria-label="Permalink to &quot;Flow A — Update the profile fields (full name, phone, professional title, bio, portfolio URLs, working language, timezone, notification preferences)&quot;">​</a></h2><ol><li>User → Client: edits the form on <code>/settings/profile</code> (full name, phone, job title, bio, portfolio URLs, working language, timezone; notification preferences have no UI yet) and clicks Save.</li><li>Client → System: <code>PUT /api/v1/users/me</code>, submitting the full set of editable fields. <ul><li>The update request carries <strong>no email field and no avatar field</strong> — they cannot be submitted through this action because there is no place to carry them, not because the system silently discards them.</li><li>An empty or blank full name is rejected at the point of entry → <code>400 VALIDATION_ERROR</code>.</li></ul></li><li>System (<code>UserServiceImpl.updateUserProfile</code>): a. System → Database: <code>UserRepository.findById(currentUser.getId())</code> — not found → <code>404 USER_NOT_FOUND</code> (theoretical). b. Writes the submitted full name (trimmed). c. When submitted (non-null), writes phone (trimmed), professionalTitle (trimmed), bio, workingLanguage (trimmed) directly onto the user record. d. When <code>portfolioUrls</code> is submitted, JSON-serializes the list and writes it to the <code>portfolioUrls</code> column — serialization failure (rare) → <code>400 INVALID_REQUEST</code>. e. Reads the stored preferences JSON, merges in the submitted timezone (when submitted) and notification preferences (when submitted), and writes the merged preferences back to the user record — serialization failure (rare) → <code>400 INVALID_REQUEST</code>.</li><li>System → Database: saves the user record.</li><li>System → Client: returns the complete updated profile — <code>userId</code>, <code>email</code>, <code>fullName</code>, <code>avatarUrl</code>, <code>phone</code>, <code>role</code>, <code>workspaceId</code>, <code>professionalTitle</code>, <code>bio</code>, <code>portfolioUrls</code>, <code>workingLanguage</code>, <code>timezone</code>, <code>notificationPreferences</code>, <code>createdAt</code> (same shape as the profile view, FR 3.3.1).</li><li>Client: shows a success confirmation and refreshes the display from the returned values, without a page reload.</li></ol><h2 id="flow-b-—-upload-an-avatar" tabindex="-1">Flow B — Upload an avatar <a class="header-anchor" href="#flow-b-—-upload-an-avatar" aria-label="Permalink to &quot;Flow B — Upload an avatar&quot;">​</a></h2><p>A separate action, independent of Flow A (never part of the profile update).</p><ol><li>User → Client: opens the avatar upload dialog and selects an image file.</li><li>Client → System: submits the selected image file (multipart).</li><li>System: a. No file, or an empty file → <code>400 NO_FILE_PROVIDED</code>. b. Content type does not start with <code>image/</code> → <code>400 INVALID_FILE_TYPE</code>. c. File larger than 5 MB → <code>400 FILE_TOO_LARGE</code>. d. System → Database: loads the user record — not found → <code>404 USER_NOT_FOUND</code> (theoretical). e. Reading the file bytes fails → <code>400 UPLOAD_FAILED</code>. f. System → File Storage: stores the image and receives the new avatar reference. g. When the user already has an avatar, System → File Storage: deletes the previous avatar file (clean-up). h. Writes the new avatar reference onto the user record → System → Database: saves the user record.</li><li>System → Client: returns the new avatar reference.</li><li>Client: shows the new avatar, replacing any temporary local preview.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>ErrorCode</th></tr></thead><tbody><tr><td>Update (Flow A)</td><td>Full name empty or blank</td><td>400</td><td><code>VALIDATION_ERROR</code></td></tr><tr><td>Update (Flow A)</td><td>Preferences or portfolioUrls data cannot be serialized (rare)</td><td>400</td><td><code>INVALID_REQUEST</code></td></tr><tr><td>Update (Flow A/B)</td><td>The user record no longer exists (theoretical)</td><td>404</td><td><code>USER_NOT_FOUND</code></td></tr><tr><td>Update (Flow A/B)</td><td>Missing, expired, or invalid token</td><td>401</td><td><code>UNAUTHORIZED</code></td></tr><tr><td>Upload avatar (Flow B)</td><td>No file provided</td><td>400</td><td><code>NO_FILE_PROVIDED</code></td></tr><tr><td>Upload avatar (Flow B)</td><td>File is not an image</td><td>400</td><td><code>INVALID_FILE_TYPE</code></td></tr><tr><td>Upload avatar (Flow B)</td><td>File larger than 5 MB</td><td>400</td><td><code>FILE_TOO_LARGE</code></td></tr><tr><td>Upload avatar (Flow B)</td><td>File cannot be read</td><td>400</td><td><code>UPLOAD_FAILED</code></td></tr></tbody></table>',13)])])}const u=t(d,[["render",i]]);export{f as __pageData,u as default};
